contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint beforeCBalance = address(c).balance;
        uint beforeSelfBalance = address(this).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterCBalance = address(c).balance;
        uint afterSelfBalance = address(this).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        if (!reverted) {
            assert(afterCBalance == beforeCBalance - value);
            assert(afterSelfBalance == beforeSelfBalance + value);
        } else {
            assert(afterCBalance == beforeCBalance);
            assert(afterSelfBalance == beforeSelfBalance);
        }
        assert(afterDeposits == beforeDeposits);
    }
}

