pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 value) internal {
        vm.deal(address(c), VALUE_CAP);
        uint beforeCBalance = address(c).balance;
        uint beforeSelfBalance = address(this).balance;
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        bool reverted;
        try c.withdraw(value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterCBalance = address(c).balance;
        uint afterSelfBalance = address(this).balance;
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        if (!reverted) {
            assert(afterCBalance == beforeCBalance - value);
            assert(afterSelfBalance == beforeSelfBalance + value);
        } else {
            assert(afterCBalance == beforeCBalance);
            assert(afterSelfBalance == beforeSelfBalance);
        }
        assertTrue(afterDeposits == beforeDeposits);
    }

    function testFuzz_run(uint256 value) public {
        _run(value);
    }

    receive() external payable {}
}
